        if (k === 1 && d > 0.7 && r() < 0.05) ferns.push({ x: x, y: lerp(b.ytF, b.ytB, 0.85), size: 10 + r() * 14 * d, ang: -Math.PI / 2 + (r() - 0.5) * 1.2, dir: r() < 0.5 ? -1 : 1, t: t + 1.2, thr: thr + 0.08, lay: "b" });
        if (k === 1 && d > 0.75 && r() < 0.05) shrooms.push({ x: x, y: lerp(b.ytF, b.ytB, 0.2 + r() * 0.7), s: 1.5 + r() * 2, t: t + 2.5 + r(), thr: thr + 0.12 });
